INSERT INTO package_questions (package_id, question_json, hash_logico, order_index, status) VALUES
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Um paciente no 5º dia de pós-operatório (PO) de ressecção de tumor de cólon esquerdo apresenta parada de eliminação de flatos e fezes, náuseas e vômitos biliosos. Ao exame, o abdome está distendido e timpanizado, com ruídos hidroaéreos discretos. A radiografia mostra alças de intestino delgado e grosso dilatadas até o sigmoide. Qual a conduta inicial mais adequada se não houver sinais de peritonite?","options":{"a":"Laparotomia exploradora imediata para desfazer possíveis bridas.","b":"Instituir jejum, passar sonda nasogástrica (SNG) em sifonagem e realizar correção de distúrbios hidroeletrolíticos.","c":"Administrar laxantes estimulantes por via oral (ex: óleo de rícino).","d":"Solicitar colonoscopia urgente para descompressão.","e":"Prescrever antibióticos de amplo espectro imediatamente."},"answer":"b","rationale":"O diagnóstico provável é de íleo adinâmico prolongado. O manejo inicial é conservador, visando o repouso intestinal e a descompressão gástrica se houver vômitos.","option_rationales":{"a":"Errada. Cirurgia deve ser reservada se houver suspeita de complicação mecânica isquêmica.","b":"Correta. Tratamento padrão inicial do íleo pós-operatório.","c":"Errada. Contraindicado em íleo adinâmico, pois pode piorar a distensão.","d":"Errada. Indicada se houver suspeita de volvo ou pseudo-obstrução colônica (Ogilvie) refratária.","e":"Errada. Antibióticos não tratam a motilidade intestinal."},"difficulty":"Fácil","tags":["Cirurgia Geral","Pós-operatório","Gastrointestinal"]}', '6d5180fb9039033d52ff03844dd80464', 50, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Sobre as ''Fístulas Digestivas'' pós-operatórias, qual é o principal objetivo da fase de ''Estabilização'' (primeiras 24-48h)?","options":{"a":"Realizar a ressecção imediata do segmento fistulizado.","b":"Reposicionar o dreno de forma percutânea.","c":"Correção da volemia, balanço eletrolítico, controle da sepse e proteção da pele peridreno.","d":"Iniciar dieta sólida hipercalórica para fechar a fístula.","e":"Administrar agentes somatostatina (Octreotide) como medida isolada única."},"answer":"c","rationale":"A mortalidade nas fístulas ocorre por desequilíbrio metabólico e sepse. Antes de qualquer decisão definitiva, o paciente deve estar estável.","option_rationales":{"a":"Errada. A cirurgia precoce em tecidos inflamados é perigosa.","b":"Errada. Pode ser necessário, mas não é o objetivo primário da estabilização global.","c":"Correta. Pilares do manejo de fístulas (Protocolo de 5 fases).","d":"Errada. O efluente aumentaria drasticamente.","e":"Errada. O octreotide pode ajudar a reduzir o débito, mas não é a prioridade inicial absoluta."},"difficulty":"Média","tags":["Cirurgia Geral","Pós-operatório","Fístulas"]}', '43b9ff6e573537aab1e0d7ef1da82204', 51, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Em um paciente com fístula enterocutânea de ''Alto Débito'' (> 500 mL/dia), qual a alteração ácido-base mais esperada devido à perda de suco entérico rico em bicarbonato?","options":{"a":"Alcalose metabólica.","b":"Acidose metabólica hiperclorêmica (anion gap normal).","c":"Acidose respiratória.","d":"Alcalose respiratória.","e":"Acidose metabólica com anion gap elevado."},"answer":"b","rationale":"A perda de bicarbonato pelo trato digestivo baixo ou fístulas entéricas leva à retenção compensatória de cloreto pelo rim, resultando em acidose hiperclorêmica.","option_rationales":{"a":"Errada. Comum em vômitos gástricos gástricos (perda de H+).","b":"Correta. Fisiopatologia ácidobase em cirurgia.","c":"Errada.","d":"Errada.","e":"Errada. Ocorreriam se houvesse choque/hipoperfusão (lactato)."},"difficulty":"Média","tags":["Cirurgia Geral","Fisiologia","Equilíbrio Ácido-Base"]}', '46287be387b8e1f0ce3bed2b5dd29c2f', 52, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Qual a via de administração de nutrientes recomendada para pacientes cirúrgicos desnutridos que não conseguem atingir 60% de suas metas calóricas por via oral, mas possuem trato gastrointestinal íntegro e funcionante?","options":{"a":"Nutrição Parenteral Total (NPT).","b":"Nutrição Enteral por sonda (SNE/Gastrostomia).","c":"Suplementos orais apenas.","d":"Hidratação venosa com glicose 5%.","e":"Uso de lipídios por veia periférica única."},"answer":"b","rationale":"O dogma ''se o intestino funciona, use-o'' permanece. A nutrição enteral mantém a barreira mucosa e tem menos complicações infecciosas que a parenteral.","option_rationales":{"a":"Errada. Indicada se o TGI estiver inacessível ou não funcionante.","b":"Correta. Diretriz de suporte nutricional.","c":"Errada. Insuficiente se já foi dito que não atinge as metas.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Cirurgia Geral","Pós-operatório","Nutrição"]}', '91cf27f01f5675df5c84b62ca2ff3d21', 53, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Um paciente no 7º dia de pós-operatório de uma anastomose colorretal baixa apresenta febre, taquicardia e dor pélvica. O toque retal revela flutuação e dor intensa. Qual a conduta indicada para este abscesso pélvico localizado, estável?","options":{"a":"Laparotomia ampla imediata.","b":"Drenagem por via transretal ou percutânea guiada por TC/USG, além de antibióticos.","c":"Manter conduta expectante apenas com analgésicos.","d":"Iniciar quimioterapia.","e":"Prescrever apenas enemas de glicerina."},"answer":"b","rationale":"Coleções pélvicas localizadas e acessíveis podem ser drenadas de forma minimamente invasiva, evitando as taxas de morbidade de uma nova laparotomia.","option_rationales":{"a":"Errada. Excessivamente invasivo para uma coleção isolada.","b":"Correta. Manejo moderno de complicações cirúrgicas.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Cirurgia Geral","Pós-operatório","Drenagem"]}', '2c7aaec3c5bb2aa7fd18fed733b4cde2', 54, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"A ''Fistulocóclise'' consiste em uma técnica de suporte nutricional que envolve:","options":{"a":"Administração de nutrientes diretamente na boca da fístula eferente.","b":"Administração de antibióticos dentro do trajeto fistuloso.","c":"Injeção de contraste para radiografia.","d":"Lavagem da fístula com soro gelado.","e":"Fechamento da fístula com cola de fibrina."},"answer":"a","rationale":"A fistulóclise permite aproveitar o restante do intestino delgado distal à fístula para absorção de nutrientes, reduzindo a dependência de NPT.","option_rationales":{"a":"Correta. Técnica nutricional específica.","b":"Errada.","c":"Errada. Isso é uma fistulografia.","d":"Errada.","e":"Errada."},"difficulty":"Difícil","tags":["Cirurgia Geral","Pós-operatório","Nutrição"]}', 'c5911f6f9e95c740f442539ed18e12f0', 55, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Qual dos seguintes achados na secreção de um dreno abdominal sugere fortemente a presença de uma fístula biliar pós-colecistectomia?","options":{"a":"Líquido amarelo-claro com Amilase elevada (> 10x valor sérico).","b":"Líquido castanho ou esverdeado com Bilirrubina total significativamente maior que a sérica.","c":"Líquido leitoso (quiloso).","d":"Líquido serossanguinolento claro.","e":"Pus espesso."},"answer":"b","rationale":"A dosagem de bilirrubina no efluente do dreno é o teste confirmatório de fístula biliar (biloma ou lesão de via biliar).","option_rationales":{"a":"Errada. Sugere fístula pancreática.","b":"Correta. Diagnóstico diferencial de efluentes de dreno.","c":"Errada. Sugere lesão de ducto torácico ou linfáticos.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Cirurgia Geral","Pós-operatório","Exames"]}', '9c6a5e346e6144e34563560632b67023', 56, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Um paciente no 4º dia de pós-operatório (PO) de duodenopancreatectomia (Whipple) apresenta saída de líquido claro pelo dreno abdominal com dosagem de ''Amilase'' três vezes maior que o limite superior da normalidade do soro. De acordo com a Sociedade Internacional de Cirurgia Pancreática (ISGPS), este achado caracteriza:","options":{"a":"Fístula Pancreática Clinicamente Relevante (Grau B/C).","b":"Vazamento Biológico (Biochemical Leak) / Fístula Grau A.","c":"Abscesso subfrênico apenas.","d":"Normalidade esperada.","e":"Hemorragia digestiva oculta."},"answer":"b","rationale":"O termo atual para o Grau A (que não altera a conduta clínica ou tempo de internação) é vazamento bioquímico. Apenas graus B e C são considerados fístulas clínicas.","option_rationales":{"a":"Errada. O Grau B/C exige mudança de conduta.","b":"Correta. Classificação ISGPS atualizada.","c":"Errada.","d":"Errada. Não é normal, mas pode não ter repercussão.","e":"Errada."},"difficulty":"Difícil","tags":["Cirurgia Geral","Pós-operatório","Pâncreas"]}', '6603f93a893d587f588d4746f6940433', 57, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"A ''Nutrição Parenteral Total'' (NPT) está associada a diversas complicações. Qual alteração metabólica hepática é frequentemente observada em pacientes em uso prolongado de NPT?","options":{"a":"Hepatite viral fulminante.","b":"Esteatose hepática e colestase (doença hepática associada à NPT).","c":"Cirrose biliar primária.","d":"Aumento súbito da albumina sérica.","e":"Câncer de fígado."},"answer":"b","rationale":"A sobrecarga de glicose e lipídios, associada à falta de estímulo enteral (ausência de liberação de CCK), predispõe ao acúmulo de gordura e estase biliar.","option_rationales":{"a":"Errada.","b":"Correta. Complicação metabólica da parenteral.","c":"Errada.","d":"Errada. A albumina é uma proteína de fase negativa e demora a subir.","e":"Errada."},"difficulty":"Média","tags":["Cirurgia Geral","Pós-operatório","Nutrição"]}', '5dd71329865c0d30202c7db3140f0d46', 58, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Qual a principal causa de ''Obstrução Intestinal Mecânica'' no pós-operatório tardio (meses a anos após a cirurgia)?","options":{"a":"Íleo adinâmico.","b":"Hérnia interna ou Bridas (aderências).","c":"Cálculo biliar impactado.","d":"Adenocarcinoma de pâncreas.","e":"Bezoar alimentar."},"answer":"b","rationale":"Aderências peritoneais são a causa número 1 de obstrução mecânica em pacientes operados previamente e não devem ser confundidas com íleo paralítico (que é funcional e precoce).","option_rationales":{"a":"Errada. É uma condição funcional precoce.","b":"Correta. Patologia cirúrgica tardia comum.","c":"Errada. (Íleo biliar).","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Cirurgia Geral","Pós-operatório","Obstrução"]}', '935d0a130bfc4378a7f5069bbeb33e00', 59, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Em relação ao manejo do ''Dreno de Sucção Fechada'' (ex: Jackson-Pratt) no pós-operatório de cirurgia abdominal, qual conduta é considerada correta para evitar a colonização retrógrada?","options":{"a":"Abrir o sistema para lavar o dreno com antisséptico diariamente.","b":"Manter o sistema fechado, esvaziar em técnica asséptica e manter o vácuo.","c":"Retirar o dreno assim que a secreção se tornar purulenta.","d":"Trocar todo o kit do dreno a cada 24 horas.","e":"Elevar o reservatório do dreno acima do nível do abdome do paciente."},"answer":"b","rationale":"O sistema fechado e o vácuo garantem a drenagem unidirecional e reduzem o risco de infecção ascendente.","option_rationales":{"a":"Errada. Aumenta gravemente o risco de infecção.","b":"Correta. Técnica cirúrgica e cuidados.","c":"Errada. Se houver pus, o dreno deve ser mantido para limpeza da cavidade e coletada cultura.","d":"Errada.","e":"Errada. Causaria refluxo de efluente para a cavidade."},"difficulty":"Fácil","tags":["Cirurgia Geral","Pós-operatório","Drenos"]}', '837ea3054c9d1536ece556d993744585', 60, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Um paciente no 6º dia de PO de esofagectomia apresenta dor torácica, febre e saída de saliva/líquido alimentar pelo dreno de tórax. A principal suspeita diagnóstica e o exame inicial são:","options":{"a":"Pneumonia; TC de tórax.","b":"Deiscência da anastomose esofágica; Esofagografia com contraste hidrossolúvel.","c":"Infarto agudo do miocárdio; Troponina.","d":"Embolia pulmonar; AngioTC.","e":"Refluxo gastroesofágico simples; pHmetria."},"answer":"b","rationale":"A deiscência de esôfago é uma complicação catastrófica que leva à mediastinite. O contraste hidrossolúvel (Gastrographin) é preferível ao bário pelo menor risco de granuloma se houver extravasamento.","option_rationales":{"a":"Errada.","b":"Correta. Diagnóstico de fístula esofágica.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Cirurgia Geral","Pós-operatório","Esôfago"]}', '1f9f6bbef672e06937813552c2f33c97', 61, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"A ''Síndrome de Realimentação'' (Refeeding Syndrome) é uma complicação grave em pacientes gravemente desnutridos que iniciam suporte nutricional. Qual alteração eletrolítica é o marco laboratorial inicial desta síndrome?","options":{"a":"Hipercalemia.","b":"Hipofosfatemia.","c":"Hipernatremias.","d":"Hipercalcemia.","e":"Hipoalbuminemia."},"answer":"b","rationale":"O aporte de glicose causa liberação de insulina, que empurra o fósforo (além de K e Mg) para dentro das células para a síntese de ATP, causando queda súbita nos níveis séricos.","option_rationales":{"a":"Errada. Ocorre hipocalemia.","b":"Correta. Fisiopatologia da realimentação.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Cirurgia Geral","Pós-operatório","Nutrição"]}', '1ddd0177a41c4e84362b63bea4fdb9b2', 62, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Um paciente submetido a uma gastrostomia para alimentação definitiva apresenta eritema e maceração da pele peri-estoma, com dor local. Qual a causa mais provável e a medida imediata?","options":{"a":"Alergia ao material da sonda; trocar a sonda.","b":"Vazamento de suco gástrico ácido (dermatite química); proteção da pele com pastas de óxido de zinco ou barreiras e ajuste do balonete.","c":"Infecção fúngica maciça; antifúngico venoso.","d":"Câncer de pele local; biópsia.","e":"Hematoma infectado; drenagem."},"answer":"b","rationale":"O suco gástrico é extremamente corrosivo. O manejo envolve o controle do vazamento e a proteção da pele íntegra.","option_rationales":{"a":"Errada.","b":"Correta. Complicação comum de estomas.","c":"Errada. Pode haver candidíase secundária, mas o efluente ácido é a causa primária.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Cirurgia Geral","Pós-operatório","Estomas"]}', '88ba55405c658f1990d7762b28f7f643', 63, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Sobre a nutrição enteral em pacientes críticos cirúrgicos, qual a conduta em relação ao ''Volume Residual Gástrico'' (VRG) monitorado pela sonda?","options":{"a":"A dieta deve ser suspensa se o VRG for maior que 50 mL.","b":"A dieta não deve ser suspensa rotineiramente apenas pelo VRG, a menos que ultrapasse 500 mL associado a sinais de intolerância (distensão, vômitos).","c":"O VRG deve ser desprezado sempre.","d":"Nutrição enteral é contraindicada se o VRG for detectável.","e":"Deve-se aspirar a sonda a cada 15 minutos."},"answer":"b","rationale":"Diretrizes recentes mostram que altos VRGs isolados não correlacionam bem com aspiração e atrasam o alcance das metas nutricionais.","option_rationales":{"a":"Errada. Valor excessivamente baixo.","b":"Correta. Prática atual baseada em evidências.","c":"Errada. Retiraria eletrólitos e suco gástrico importantes.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Cirurgia Geral","Pós-operatório","Nutrição"]}', 'c8916c60a19252dacf0c709c8968cef5', 64, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Qual a principal indicação para ''Nutrição Parenteral Periférica'' (NPP)?","options":{"a":"Necessidade de suporte nutricional total por mais de 3 semanas.","b":"Suporte nutricional de curto prazo (< 10-14 dias) em pacientes que não toleram via enteral e não possuem acesso central.","c":"Pacientes com restrição hídrica severa.","d":"Fístula de alto débito crônica.","e":"Insuficiência renal em anúria."},"answer":"b","rationale":"A NPP possui baixa osmolaridade (<900 mOsm/L) para não causar flebite, o que limita sua concentração calórica. É apenas uma ponte temporária.","option_rationales":{"a":"Errada. Exigiria acesso central (NPT).","b":"Correta. Uso racional da nutrição parenteral.","c":"Errada. NPP exige grandes volumes devido à baixa concentração.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Cirurgia Geral","Pós-operatório","Nutrição"]}', '680ddcfcb7c0e1fde2069ba562202e69', 65, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"O ''Dreno de Penrose'' é classificado como um dreno do tipo:","options":{"a":"Ativo por sucção.","b":"Passivo por capilaridade.","c":"Passivo por gravidade puro (sistema fechado).","d":"Dreno de som de alta frequência.","e":"Válvula unidirecional."},"answer":"b","rationale":"O dreno de Penrose é uma lâmina de látex aberta; o fluido sai pela superfície do dreno e é absorvido pelas gazes do curativo.","option_rationales":{"a":"Errada. (Ex: Port-o-vac).","b":"Correta. Tipo de dreno fundamental.","c":"Errada. (Ex: sonda de Malecot ou dreno em T).","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Cirurgia Geral","Pós-operatório","Drenos"]}', 'aa2135f2790c6b74c692cb195792e60f', 66, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Em relação à ''Cicatrização'' de mucosas e pele, qual micronutriente é cofator essencial para a hidroxilação da prolina e lisina na síntese de colágeno, sendo sua deficiência causa de deiscências?","options":{"a":"Vitamina B12.","b":"Vitamina C (Ácido Ascórbico).","c":"Vitamina E.","d":"Sódio.","e":"Magnésio."},"answer":"b","rationale":"A vitamina C é indispensável para a estabilidade da tripla hélice do colágeno. O escorbuto é a manifestação extrema dessa deficiência.","option_rationales":{"a":"Errada.","b":"Correta. Bioquímica aplicada à cirurgia.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Cirurgia Geral","Fisiologia","Cicatrização"]}', 'a2e6804bcdc8ed0fb01843c84d613eb8', 67, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Paciente no 8º dia de PO de coledocoscopia com colocação de Dreno de Kher (dreno em T). Observa-se saída de 400 mL de bile limpa no reservatório. No dia seguinte, o débito cai para zero e o paciente apresenta dor no hipocôndrio direito. Qual a conduta inicial?","options":{"a":"Retirar o dreno imediatamente puxando com força.","b":"Verificar se o dreno está dobrado ou obstruído e tentar lavagem suave com SF estéril.","c":"Indicar CPRE imediata.","d":"Laparotomia exploradora.","e":"Prescrever apenas morfina para a dor."},"answer":"b","rationale":"A interrupção súbita do débito biliar seguida de dor sugere obstrução mecânica do dreno, o que pode causar hipertensão biliar e dor.","option_rationales":{"a":"Errada. O dreno em T não deve ser retirado antes de 14-21 dias.","b":"Correta. Solução de problemas com drenos.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Cirurgia Geral","Pós-operatório","Dreno de Kher"]}', '082630ead5152b2a003a1b4e70a29812', 68, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"A fístula pancreática é uma das complicações mais temidas após traumas ou cirurgias. Qual a classe de medicamentos que pode ser utilizada para reduzir a secreção pâncreato-digestiva e auxiliar no fechamento espontâneo?","options":{"a":"Agonistas Beta-adrenérgicos.","b":"Inibidores da bomba de prótons.","c":"Análogos da Somatostatina (Octreotide).","d":"Antidiuréticos.","e":"Glicocorticoides."},"answer":"c","rationale":"O octreotide inibe a liberação de diversos hormônios gastrointestinais e reduz o volume de secreção gástrica, biliar e pancreática.","option_rationales":{"a":"Errada.","b":"Errada. Reduz o ácido, mas tem pouco impacto no pâncreas exócrino.","c":"Correta. Manejo farmacológico de fístulas.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Cirurgia Geral","Pós-operatório","Fístulas"]}', '56f34efa92e71de0a924ed41c891fe20', 69, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Em pacientes com fístula enterocutânea exposta, qual o método preferencial para manejar o efluente e proteger a ferida quando a produção de líquido é muito volumosa e irritante?","options":{"a":"Uso de curativo a vácuo (Terapia por Pressão Negativa) adaptado para isolamento da fístula.","b":"Gazes secas trocadas a cada 15 minutos.","c":"Deixar a ferida exposta ao ar para secar.","d":"Cobrir com filme plástico transparente sem orifícios.","e":"Uso de talco comum."},"answer":"a","rationale":"O curativo a vácuo ajuda a colher o efluente sem que ele toque a pele sã e estimula a formação de tecido de granulação ao redor da fístula.","option_rationales":{"a":"Correta. Tecnologia em curativos complexos.","b":"Errada. Inviável e não protege a pele contra maceração.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Cirurgia Geral","Pós-operatório","Feridas Complexas"]}', 'bed9603d19b7846d153298f4863c13f9', 70, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Qual o tempo mínimo de jejum pré-operatório recomendado pela Sociedade Brasileira de Anestesiologia (SBA) para líquidos claros (água, chá, sucos sem resíduo)?","options":{"a":"8 horas.","b":"6 horas.","c":"2 horas.","d":"12 horas.","e":"Jejum absoluto desde a meia-noite anterior."},"answer":"c","rationale":"Líquidos claros deixam o estômago rapidamente, e o jejum prolongado causa desidratação e estresse metabólico desnecessário.","option_rationales":{"a":"Errada. Reservado para refeições gordurosas.","b":"Errada. Reservado para refeições leves/leite de vaca.","c":"Correta. Recomendação de protocolos modernos.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Cirurgia Geral","Pós-operatório","Jejum"]}', 'a3e8062b0cf5a001624c087d0224704d', 71, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"A ''Deiscência de Anastomose'' colorretal costuma manifestar-se mais frequentemente em qual período?","options":{"a":"Nas primeiras 12 horas.","b":"Entre o 2º e o 3º PO.","c":"Entre o 5º e o 8º PO.","d":"Apenas após o 30º dia.","e":"Exatamente no 1º PO."},"answer":"c","rationale":"É o período em que a lise do colágeno antigo já ocorreu, mas o colágeno novo ainda não atingiu resistência mecânica suficiente.","option_rationales":{"a":"Errada.","b":"Errada.","c":"Correta. Período crítico de cicatrização intestinal.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Cirurgia Geral","Pós-operatório","Cicatrização"]}', '7a35054ba8cd7e9a64594ebecf2919fc', 72, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"Um paciente submetido a cirurgia abdominal desenvolve quadro de dor, distensão e parada de flatos no 4º PO. A radiografia mostra níveis hidroaéreos e distensão central de alças. Se o diagnóstico for ''Obstrução Mecânica Cedo no Pós-operatório'' (early postoperative bowel obstruction), por quanto tempo deve-se tentar o manejo conservador antes de reoperar?","options":{"a":"Máximo de 6 horas.","b":"Até 10 a 14 dias, se não houver sinais de isquemia ou peritonite.","c":"Reoperação deve ser imediata em 100% dos casos.","d":"Jejum por 1 mês.","e":"Antibiótico por 21 dias."},"answer":"b","rationale":"A maioria das obstruções precoces deve-se a aderências inflamatórias que podem se resolver com repouso intestinal; a cirurgia precoce é tecnicamente difícil e arriscada.","option_rationales":{"a":"Errada.","b":"Correta. Manejo expectante de obstrução funcional/inflamatória precoce.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Difícil","tags":["Cirurgia Geral","Pós-operatório","Obstrução"]}', 'ed4b7e0c828ad438d010d581513df59c', 73, 'draft'),
('1dff6a37-e7d4-40c0-9d91-9d8cd72a4360', '{"enunciado":"O principal dreno utilizado para monitorar se há vazamento da via biliar após uma cirurgia de exploração de colédoco é:","options":{"a":"Dreno de vácuo.","b":"Sonda de Foley.","c":"Dreno de Kehr (em T).","d":"Dreno de Blake.","e":"Tubo de toracostomia."},"answer":"c","rationale":"O dreno de Kehr é inserido diretamente no colédoco para drenagem biliar e realização de colangiografia pós-op.","option_rationales":{"a":"Errada.","b":"Errada.","c":"Correta. Dreno biliar clássico.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Cirurgia Geral","Pós-operatório","Drenos"]}', '250896e3f7f7357c04bb2008bb2cb6e7', 74, 'draft');